input.command:
$path = 'F:\obsidian_notes\knowledge\TOEFL\邮件写作\询问朋友帮忙动物救助慈善活动.md'
$lines = Get-Content -LiteralPath $path -Encoding UTF8
function Find-Idx([string]$sub, [int]$start) {
  for ($i = $start; $i -lt $lines.Count; $i++) {
    if ($lines[$i].Contains($sub)) { return $i }
  }
  return -1
}
$a = Find-Idx '# 我的回答' 0
$b = Find-Idx '# 改正版（2026-10-18，AI参考估分 4/6）' $a
$c = Find-Idx '（原文194词' $b
$d = Find-Idx '估分说明：' $c
Write-Output "anchor idx: a=$a b=$b c=$c d=$d"
function Count-Words([string[]]$seg, [bool]$stripBold) {
  $total = 0
  foreach ($ln in $seg) {
    $t = $ln
    if ($stripBold) { $t = $t.Replace('**', '') }
    $total += ($t.Split([char[]]@(' ', "`t", "`r"), [System.StringSplitOptions]::RemoveEmptyEntries)).Count
  }
  return $total
}
$origSeg = $lines[($a+1)..($b-1)]
$corrSeg = $lines[($b+1)..($c-1)]
$n1 = Count-Words $origSeg $false
$n2 = Count-Words $origSeg $false
$m1 = Count-Words $corrSeg $true
$m2 = Count-Words $corrSeg $true
Write-Output "original  pass1=$n1 pass2=$n2"
Write-Output "corrected pass1=$m1 pass2=$m2"
$joined = ($corrSeg -join "`n")
$boldCount = ([regex]::Matches($joined, '\*\*')).Count
Write-Output "bold markers in corrected email: $boldCount"
